//! PPTX-11: 预设几何形状（OOXML `a:prstGeom`）公式求值系统。
//!
//! 架构依据：roe-ext 调研已确认 LOK（`presetShapeDefinitions.xml`）与
//! OnlyOffice（`CreateGeometry.js` + `Geometry.js` 的 `CalculateGuideValue`）
//! 两套独立生产实现在 fmla 公式语义上完全一致（含 pin=clamp、mod=三维欧氏
//! 距离等易混淆项，均已交叉验证）。本文件的求值逻辑直接对照 OnlyOffice
//! `Geometry.js` 第100-282行 `CalculateGuideValue`/`CalculateGuideLst`
//! 移植，因为该实现给出了完整、可运行的参照（LOK 的 XML 只是"数据"，
//! OnlyOffice 是"数据+求值器"合一的完整实现，更适合直接对照）。
//!
//! 求值时机：解析阶段（roadmap 方案A拍板依据：ROE 当前是只读渲染链路，
//! 不支持编辑场景下的实时重算，见 PPTX-11-preliminary-research{,-part2}.md）。
//! 具体 Shape 的 w/h/adj1..N 一旦从 XML 读出即固定，此处一次性代入求值成
//! 绝对坐标路径，不保留符号引用。
//!
//! 求值顺序：OnlyOffice `CalculateGuideLst` 是对 `gdLstInfo` 数组的线性
//! 遍历（非拓扑排序），依赖"guide 定义在源数据里天然按依赖顺序排列（被
//! 引用的 guide 一定先于引用它的 guide 定义）"这一事实。187种预设形状的
//! 原始数据（无论抄自 LOK 的 XML 还是 OnlyOffice 的 JS case）均满足此
//! 顺序，因此本实现同样用线性遍历，不实现拓扑排序，与两个参照实现的
//! 假设保持一致。
//!
//! 第一期范围（本次会话，架构落地）：约30种高频形状，未覆盖的形状名字
//! 继续落入 `ShapeGeometry::Custom(String)`（现状不变）。**这是过渡方案，
//! 非终态**——后续会话会持续追加形状数据，目标覆盖 OOXML 全部187种预设
//! 几何（含 OnlyOffice 侧统计的227个case，去除 WordArt 文字变形与连接线
//! 后约188种属于本模块范畴）。见 roe-ext_roadmp.md PPTX-11 条目。

use std::collections::HashMap;
use crate::common::{PathCommand, ConnectionPoint, Transform};

/// fmla 公式操作码。命名与语义对照 OnlyOffice `Geometry.js` 第175-270行
/// `switch(formula)` 分支逐一核实，行号出处见调研笔记
/// `PPTX-11-preliminary-research-part2.md`。
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum GuideOp {
    /// `*/`  三参：(a*b)/c
    MulDiv,
    /// `+-`  三参：a+b-c
    PlusMinus,
    /// `+/`  三参：(a+b)/c
    PlusDiv,
    /// `ifelse`/`?:` 三参：if a>0 then b else c（判定严格大于0，非>=0，
    /// 已按 OnlyOffice `if(xt>0)` 精确核实）
    IfElse,
    /// `abs` 一参：|a|
    Abs,
    /// `at2` 二参：atan2(b, a) 换算成 1/60000 度单位。
    /// 注意 atan2 参数顺序是 (y=b, x=a)，即第二个guide参数是y分量。
    At2,
    /// `cat2` 三参：a * cos(atan2(c, b))
    Cat2,
    /// `cos` 二参：a * cos(b)，b 单位 1/60000 度
    Cos,
    /// `max` 二参
    Max,
    /// `min` 二参
    Min,
    /// `mod` 三参：sqrt(a² + b² + c²)（三维欧氏距离/斜边长度，
    /// **不是取模运算**，二维场景常见写法是第三参传0退化成勾股定理）
    Mod,
    /// `pin` 三参：clamp。参数语义为 (min=a, val=b, max=c)：
    /// 若 b<a 结果为a；若 b>c 结果为c；否则结果为b。
    /// 已用 LOK `if(x-y,x,if(z-y,z,y))` 与 OnlyOffice
    /// `if(yt<xt) xt; else if(yt>zt) zt; else yt` 双重独立验证一致。
    Pin,
    /// `sat2` 三参：a * sin(atan2(c, b))
    Sat2,
    /// `sin` 二参：a * sin(b)，b 单位 1/60000 度
    Sin,
    /// `sqrt` 一参
    Sqrt,
    /// `tan` 二参：a * tan(b)，b 单位 1/60000 度
    Tan,
    /// `val` 一参：常量赋值
    Value,
}

/// guide 公式的参数引用：可能是具名变量（形状自身的 w/h/l/t/r/b/hc/vc、
/// adj1..N、其他已定义 guide 的 name），也可能是字面数值常量。
#[derive(Debug, Clone)]
pub enum GuideRef {
    /// 具名引用，运行时从当前求值上下文（内置变量 + adj + 已求值 guide）查找
    Named(&'static str),
    /// 字面数值常量（对应 fmla 里直接写数字的参数，如 `"*/ w adj1 100000"`
    /// 里的 `100000`）
    Literal(f64),
}

impl GuideRef {
    /// 语法糖：数值字面量场景可以直接写
    pub const fn lit(v: f64) -> Self {
        GuideRef::Literal(v)
    }
    pub const fn named(name: &'static str) -> Self {
        GuideRef::Named(name)
    }
}

/// 单条 guide 定义：`name = op(args...)`，对应 OOXML `<gd name=".." fmla="..">`
/// / OnlyOffice `f.AddGuide(name, op, x, y, z)` 调用。
#[derive(Debug, Clone)]
pub struct GuideDef {
    pub name: &'static str,
    pub op: GuideOp,
    /// 固定长度3，未使用的参数位置按 op 的元数不读取。用数组而非 Vec
    /// 是因为所有12种操作码参数个数都 <=3（与 OnlyOffice/LOK 一致，
    /// LOK 侧甚至显式硬编码了 nParameters>3 截断为3的保护逻辑）。
    pub args: [GuideRef; 3],
}

/// 路径指令（求值前，符号形式），对应 OOXML `a:pathLst` 内的绘制元素。
/// 求值后转换成 `crate::common::PathCommand`（具体坐标，渲染层消费）。
#[derive(Debug, Clone)]
pub enum PathCmdDef {
    MoveTo { x: GuideRef, y: GuideRef },
    LineTo { x: GuideRef, y: GuideRef },
    /// 三次贝塞尔，对应 `a:cubicBezTo`（内含3个 `a:pt`）
    CubicTo {
        x1: GuideRef, y1: GuideRef,
        x2: GuideRef, y2: GuideRef,
        x:  GuideRef, y:  GuideRef,
    },
    /// 二次贝塞尔，对应 `a:quadBezTo`（内含2个 `a:pt`：控制点+终点）
    QuadTo {
        x1: GuideRef, y1: GuideRef,
        x:  GuideRef, y:  GuideRef,
    },
    /// 圆弧，对应 `a:arcTo`，属性为 wR/hR（半径）+ stAng/swAng（起始角/
    /// 扫过角，1/60000度单位）。OOXML `arcTo` 不显式给终点坐标，终点由
    /// 圆弧几何计算得出。**已知局限**：当前求值器不追踪绘制游标（笔
    /// 当前位置），ArcTo 求值结果的 cx/cy 暂为占位值 0.0，后续移植到
    /// 实际使用 arcTo 的形状时需要回来补上游标追踪（TODO）。
    ArcTo { wr: GuideRef, hr: GuideRef, st_ang: GuideRef, sw_ang: GuideRef },
    Close,
}

/// 单个连接点定义，对应 OOXML `<a:cxn ang=".." ><a:pos x=".." y=".." /></a:cxn>`
/// / OnlyOffice `f.AddCnx(ang, x, y)` 调用。`idx`（数组下标）即连接点编号，
/// 与 OOXML `cxn` 的隐式顺序一致：**调用/声明顺序即 idx**，无排序或去重逻辑
/// （已用 OnlyOffice CreateGeometry.js 的 `Geometry.prototype.AddCnx` 实现和
/// LOK `presetShapeDefinitions.xml` 交叉核对确认，2026-09）。
#[derive(Debug, Clone)]
pub struct CxnDef {
    pub ang: GuideRef,
    pub x: GuideRef,
    pub y: GuideRef,
}

/// 一个预设形状的完整"公式模板"（求值前，编译期静态数据，用 Rust 代码
/// 以链式调用风格构造，而非运行时解析字符串——理由：187个形状会陆续在
/// 多次会话中添加，函数调用形式让参数个数/类型错误在编译期暴露，比字符串
/// 拼装更不容易出现"拼错但不报错"的隐蔽 bug，翻译时也能与 OnlyOffice
/// 原始 `f.AddGuide(...)` 调用逐行对照，降低翻译出错概率）。
#[derive(Debug, Clone)]
pub struct PresetShapeFormula {
    pub name: &'static str,
    /// adj 参数默认值（对应 OOXML `<a:avLst>`），形状实例若在 XML 里
    /// 显式覆盖了某个 adjN，解析层用覆盖值替换此处默认值再求值。
    pub default_adj: &'static [(&'static str, f64)],
    /// guide 定义序列，**求值顺序即数组顺序**（线性遍历，不做拓扑排序，
    /// 见模块顶部说明），移植时必须保持与源参照（OnlyOffice case）相同
    /// 的调用顺序。
    pub guides: &'static [GuideDef],
    /// 路径指令序列（符号形式，求值后转具体坐标）
    pub path: &'static [PathCmdDef],
    /// 连接点列表，对应 OOXML `<a:cxnLst>`。无连接点定义的形状（如connector
    /// 家族自身）填 `&[]`，不panic。2026-09 新增字段，174/187 个形状有非空
    /// cxnLst（其余13个多为connector家族，语义上"连接别人的"不需要自身被连接）。
    pub cxn_lst: &'static [CxnDef],
}

/// 内置几何常量（对应 OnlyOffice `Geometry.js` 第111-119行 `oGdLst` 预置
/// 表），单位统一为 1/60000 度（角度类）或与 w/h 同量纲（长度类）。
fn builtin_constants(w: f64, h: f64) -> HashMap<&'static str, f64> {
    let mut m = HashMap::new();
    m.insert("_3cd4", 16_200_000.0);
    m.insert("_3cd8", 8_100_000.0);
    m.insert("_5cd8", 13_500_000.0);
    m.insert("_7cd8", 18_900_000.0);
    m.insert("cd2", 10_800_000.0);
    m.insert("cd4", 5_400_000.0);
    m.insert("cd8", 2_700_000.0);
    m.insert("l", 0.0);
    m.insert("t", 0.0);
    m.insert("r", w);
    m.insert("b", h);
    m.insert("w", w);
    m.insert("h", h);
    m.insert("hc", w / 2.0);
    m.insert("vc", h / 2.0);
    m.insert("ss", w.min(h));
    m.insert("wd2", w / 2.0);
    m.insert("hd2", h / 2.0);
    // 以下为 OnlyOffice Geometry.js 第1220-1258行 gdLst 静态表补充的完整
    // 分数尺寸常量（w/N、h/N、ss/N 系列），PPTX-11批量脚本生成的形状数据
    // 中多个形状引用了本次之前未覆盖的档位（如 hd4/wd8/ssd6 等），一并
    // 按源码补齐全部档位，避免后续形状再逐个发现缺口。
    m.insert("wd3", w / 3.0);
    m.insert("wd4", w / 4.0);
    m.insert("wd5", w / 5.0);
    m.insert("wd6", w / 6.0);
    m.insert("wd8", w / 8.0);
    m.insert("wd10", w / 10.0);
    m.insert("wd12", w / 12.0);
    m.insert("wd32", w / 32.0);
    m.insert("hd3", h / 3.0);
    m.insert("hd4", h / 4.0);
    m.insert("hd5", h / 5.0);
    m.insert("hd6", h / 6.0);
    m.insert("hd8", h / 8.0);
    m.insert("hd10", h / 10.0);
    m.insert("hd12", h / 12.0);
    m.insert("hd32", h / 32.0);
    m.insert("ls", w.max(h));
    m.insert("ssd2", w.min(h) / 2.0);
    m.insert("ssd4", w.min(h) / 4.0);
    m.insert("ssd6", w.min(h) / 6.0);
    m.insert("ssd8", w.min(h) / 8.0);
    m.insert("ssd16", w.min(h) / 16.0);
    m.insert("ssd32", w.min(h) / 32.0);
    m
}

/// 1/60000 度 转弧度
const C_TO_RAD: f64 = std::f64::consts::PI / (60_000.0 * 180.0);
/// 弧度 转 1/60000 度
const C_TO_DEG: f64 = 1.0 / C_TO_RAD;

fn eval_cos(angle_60000th_deg: f64) -> f64 { (angle_60000th_deg * C_TO_RAD).cos() }
fn eval_sin(angle_60000th_deg: f64) -> f64 { (angle_60000th_deg * C_TO_RAD).sin() }
fn eval_tan(angle_60000th_deg: f64) -> f64 { (angle_60000th_deg * C_TO_RAD).tan() }
fn eval_atan2(y: f64, x: f64) -> f64 { y.atan2(x) * C_TO_DEG }

/// 单条 guide 公式求值。`ctx` 是当前已求值完毕的变量表（内置常量 + adj +
/// 已求值 guide 的并集），求值结果写回 `ctx`。
///
/// 对照 OnlyOffice `CalculateGuideValue`（`Geometry.js` 第161-270行）
/// 逐分支移植，含该函数末尾 `if(isNaN(...)) gdLst[name]=0` 的 NaN 兜底
/// （避免非法输入导致后续路径计算全链路传播 NaN）。
fn eval_guide(def: &GuideDef, ctx: &mut HashMap<&'static str, f64>) {
    let resolve = |r: &GuideRef, ctx: &HashMap<&'static str, f64>| -> f64 {
        match r {
            GuideRef::Literal(v) => *v,
            GuideRef::Named(n) => *ctx.get(n).unwrap_or(&0.0),
        }
    };
    let x = resolve(&def.args[0], ctx);
    let y = resolve(&def.args[1], ctx);
    let z = resolve(&def.args[2], ctx);

    let result = match def.op {
        GuideOp::MulDiv => if z != 0.0 { x * y / z } else { 0.0 },
        GuideOp::PlusMinus => x + y - z,
        GuideOp::PlusDiv => if z != 0.0 { (x + y) / z } else { 0.0 },
        GuideOp::IfElse => if x > 0.0 { y } else { z },
        GuideOp::Abs => x.abs(),
        GuideOp::At2 => eval_atan2(y, x),
        // cat2(a,b,c) = a * cos(atan2(c,b))，与 sat2 同源不同三角函数，
        // 已按 LOK CAt2()/OnlyOffice CAt2() 双重核实，注意 atan2 参数顺序
        // 是 (z,y) 不是 (y,z)。
        GuideOp::Cat2 => x * eval_cos(eval_atan2(z, y)),
        GuideOp::Cos => x * eval_cos(y),
        GuideOp::Max => x.max(y),
        GuideOp::Min => x.min(y),
        GuideOp::Mod => (x * x + y * y + z * z).sqrt(),
        GuideOp::Pin => if y < x { x } else if y > z { z } else { y },
        GuideOp::Sat2 => x * eval_sin(eval_atan2(z, y)),
        GuideOp::Sin => x * eval_sin(y),
        GuideOp::Sqrt => x.sqrt(),
        GuideOp::Tan => x * eval_tan(y),
        GuideOp::Value => x,
    };
    let result = if result.is_nan() { 0.0 } else { result };
    ctx.insert(def.name, result);
}

/// 对一个预设形状公式模板 + 具体实例的 w/h/adj 覆盖值，求值出最终绝对
/// 坐标路径。这是本模块对外的核心入口，解析层（pptx.rs）持有
/// `PresetShapeFormula` 静态数据表，读到具体 `<p:sp>` 的 `prstGeom`
/// 后调用本函数。
///
/// `w`/`h`：形状的宽高（pt，与 ROE 既有"解析阶段统一转换单位"约定一致）。
/// `adj_overrides`：该 shape 在 XML `<a:avLst>` 里显式覆盖的 adj 值
/// （用户拖拽调整点后 PowerPoint 写回的值），未覆盖的 adjN 使用
/// `formula.default_adj` 的默认值。
pub fn eval_preset_shape(
    formula: &PresetShapeFormula,
    w: f64,
    h: f64,
    adj_overrides: &HashMap<&str, f64>,
) -> Vec<PathCommand> {
    let mut ctx = builtin_constants(w, h);

    for &(name, default_val) in formula.default_adj {
        let val = adj_overrides.get(name).copied().unwrap_or(default_val);
        ctx.insert(name, val);
    }

    for guide in formula.guides {
        eval_guide(guide, &mut ctx);
    }

    let resolve = |r: &GuideRef, ctx: &HashMap<&'static str, f64>| -> f64 {
        match r {
            GuideRef::Literal(v) => *v,
            GuideRef::Named(n) => *ctx.get(n).unwrap_or(&0.0),
        }
    };

    // 绘制游标：追踪"当前笔位置"，供 ArcTo 反推圆心使用。OOXML arcTo 不显式
    // 给终点坐标，终点由 wR/hR（局部椭圆半径）+ stAng/swAng（1/60000度）反推：
    // LOK EnhancedCustomShape2d.cxx 第2440-2442行证实椭圆在局部坐标系里定义，
    // 左上角为(0,0)，局部圆心恒为(wR,hR)；stAng处椭圆上的点相对局部圆心的偏移
    // 是 (wR*cos(stAng), hR*sin(stAng))，该点必须与当前游标位置重合（弧的起点
    // 衔接前一笔画终点），故：全局圆心 = 游标位置 - (wR*cos(stAng), hR*sin(stAng))。
    // 弧结束后游标更新为终点：圆心 + (wR*cos(stAng+swAng), hR*sin(stAng+swAng))，
    // 保证后续 LineTo/ArcTo 正确衔接。
    let mut cur_x = 0.0_f64;
    let mut cur_y = 0.0_f64;
    let mut out = Vec::with_capacity(formula.path.len());

    for cmd in formula.path {
        let path_cmd = match cmd {
            PathCmdDef::MoveTo { x, y } => {
                let (x, y) = (resolve(x, &ctx), resolve(y, &ctx));
                cur_x = x;
                cur_y = y;
                PathCommand::MoveTo { x: x as f32, y: y as f32 }
            }
            PathCmdDef::LineTo { x, y } => {
                let (x, y) = (resolve(x, &ctx), resolve(y, &ctx));
                cur_x = x;
                cur_y = y;
                PathCommand::LineTo { x: x as f32, y: y as f32 }
            }
            PathCmdDef::CubicTo { x1, y1, x2, y2, x, y } => {
                let (x1v, y1v) = (resolve(x1, &ctx), resolve(y1, &ctx));
                let (x2v, y2v) = (resolve(x2, &ctx), resolve(y2, &ctx));
                let (xv, yv) = (resolve(x, &ctx), resolve(y, &ctx));
                cur_x = xv;
                cur_y = yv;
                PathCommand::CubicTo {
                    x1: x1v as f32, y1: y1v as f32,
                    x2: x2v as f32, y2: y2v as f32,
                    x: xv as f32, y: yv as f32,
                }
            }
            PathCmdDef::QuadTo { x1, y1, x, y } => {
                let (x1v, y1v) = (resolve(x1, &ctx), resolve(y1, &ctx));
                let (xv, yv) = (resolve(x, &ctx), resolve(y, &ctx));
                cur_x = xv;
                cur_y = yv;
                PathCommand::QuadTo {
                    x1: x1v as f32, y1: y1v as f32,
                    x: xv as f32, y: yv as f32,
                }
            }
            PathCmdDef::ArcTo { wr, hr, st_ang, sw_ang } => {
                let wr_v = resolve(wr, &ctx);
                let hr_v = resolve(hr, &ctx);
                let st_ang_v = resolve(st_ang, &ctx); // 1/60000度，原始单位，直接喂给 eval_cos/eval_sin
                let sw_ang_v = resolve(sw_ang, &ctx);

                let cx = cur_x - wr_v * eval_cos(st_ang_v);
                let cy = cur_y - hr_v * eval_sin(st_ang_v);

                // 弧终点，更新游标供后续指令衔接
                let end_ang_v = st_ang_v + sw_ang_v;
                cur_x = cx + wr_v * eval_cos(end_ang_v);
                cur_y = cy + hr_v * eval_sin(end_ang_v);

                PathCommand::ArcTo {
                    cx: cx as f32, cy: cy as f32,
                    rx: wr_v as f32, ry: hr_v as f32,
                    start_deg: st_ang_v as f32, sweep_deg: sw_ang_v as f32,
                }
            }
            PathCmdDef::Close => PathCommand::Close,
        };
        out.push(path_cmd);
    }

    out
}

/// 求值形状的连接点列表（本地坐标系，未经 Transform 映射，见
/// roe-ext_progress_v179.md 二.6节关于全局坐标映射的单独讨论）。
///
/// 复用 `eval_preset_shape` 同一套 `ctx` 构建逻辑（内置常量 + adj覆盖 +
/// guides线性求值），因为 `cxn_lst` 里的 GuideRef 与 `path` 共享同一套
/// 具名变量语义（形状私有guide、内置l/t/r/b/hc/vc等），必须用同一个
/// 已求值完毕的 `ctx` 才能正确解析，不能独立于 path 求值单独计算。
///
/// 与 `eval_preset_shape` 的关键差异：不需要绘制游标追踪（`cxn_lst` 的
/// 每一条都是绝对引用，不像 `ArcTo` 依赖"前一笔画终点"这种相对信息），
/// 因此实现比 `eval_preset_shape` 简单，无游标状态。
pub fn get_connection_points(
    formula: &PresetShapeFormula,
    w: f64,
    h: f64,
    adj_overrides: &HashMap<&str, f64>,
) -> Vec<ConnectionPoint> {
    let mut ctx = builtin_constants(w, h);

    for &(name, default_val) in formula.default_adj {
        let val = adj_overrides.get(name).copied().unwrap_or(default_val);
        ctx.insert(name, val);
    }

    for guide in formula.guides {
        eval_guide(guide, &mut ctx);
    }

    let resolve = |r: &GuideRef, ctx: &HashMap<&'static str, f64>| -> f64 {
        match r {
            GuideRef::Literal(v) => *v,
            GuideRef::Named(n) => *ctx.get(n).unwrap_or(&0.0),
        }
    };

    formula
        .cxn_lst
        .iter()
        .enumerate()
        .map(|(idx, cxn)| ConnectionPoint {
            idx,
            angle_60000th_deg: resolve(&cxn.ang, &ctx) as f32,
            x: resolve(&cxn.x, &ctx) as f32,
            y: resolve(&cxn.y, &ctx) as f32,
        })
        .collect()
}

/// PPTX-11 后续：将 `get_connection_points` 求出的本地坐标系连接点，
/// 映射为文档全局坐标。设计依据见 roe-ext_progress_v180.md 第3.2/3.3节：
///
/// - 本函数只消费 `Transform` 的 `offset`/`extent`/`rotation`/`flip_h`/
///   `flip_v` 五个字段，**有意不读取 `shear_x`/`shear_y`**——这两个字段
///   在 OOXML 中实际对应 `<a:effectLst>` 下的 `TransformEffect`（视觉
///   特效层的 skew），与 `<a:xfrm>`（形状空间几何定位）是两个不同的
///   OOXML 元素，只是恰好都叫 `xfrm`/都有 kx/ky 而被此前实现混淆。
///   `Transform` 结构体本身保留这两个字段是历史原因（v178 已上线的
///   C-ABI 读写通路，非本次改动范围），但任何新的空间几何映射逻辑
///   都不应该把 shear 当成真正的形状旋转/翻转的一部分来处理。
///   若未来看到本函数没有用 shear，这是有意为之，不是遗漏。
///
/// 推导顺序（已用 Gemini 交叉核对，避免"绕左上角旋转"这类常见错误）：
/// 1. 本地坐标转换为相对形状中心的坐标：`(x - w/2, y - h/2)`
/// 2. 应用 flip_h（x 取反）
/// 3. 应用 flip_v（y 取反）——与现有渲染层 `tile_render_helpers.rs`
///    的 `y' = -y + 2*sy + h_px` 公式本质等价，只是那个公式是在未平移
///    到中心的绝对坐标系下推导的；转换到"相对中心"坐标系后化简为单纯
///    取反，可以与 flip_h 统一处理
/// 4. 应用 rotation（绕原点即形状中心，做二维旋转，θ 为顺时针角度，
///    与现有代码 `tiny_skia::Transform::from_rotate_at` 顺时针语义一致）：
///    `x' = x*cosθ - y*sinθ`, `y' = x*sinθ + y*cosθ`
/// 5. 加回形状中心的文档绝对坐标：
///    `(offset.0 + w/2 + x', offset.1 + h/2 + y')`
///
/// 变换顺序为"先 flip 再 rotate"，与现有渲染层
/// （WROOT-XLSX-SHAPE-ROT-01：flip_v 在前，rotation 在后）保持一致。
pub fn map_connection_point_to_global(
    point: &ConnectionPoint,
    transform: &Transform,
) -> (f32, f32) {
    let (w, h) = transform.extent;
    let (ox, oy) = transform.offset;

    // 第1步：本地坐标 -> 相对形状中心的坐标
    let mut x = point.x - w / 2.0;
    let mut y = point.y - h / 2.0;

    // 第2步：flip_h
    if transform.flip_h.unwrap_or(false) {
        x = -x;
    }

    // 第3步：flip_v
    if transform.flip_v.unwrap_or(false) {
        y = -y;
    }

    // 第4步：rotation（顺时针，普通角度制，绕形状中心/当前坐标系原点）
    if let Some(rot_deg) = transform.rotation {
        if rot_deg != 0.0 {
            let theta = rot_deg.to_radians();
            let (sin_t, cos_t) = theta.sin_cos();
            let rx = x * cos_t - y * sin_t;
            let ry = x * sin_t + y * cos_t;
            x = rx;
            y = ry;
        }
    }

    // 第5步：加回形状中心的文档绝对坐标
    (ox + w / 2.0 + x, oy + h / 2.0 + y)
}

#[cfg(test)]
mod connection_transform_tests {
    use super::*;

    fn cp(x: f32, y: f32) -> ConnectionPoint {
        ConnectionPoint { idx: 0, angle_60000th_deg: 0.0, x, y }
    }

    fn transform_with(
        offset: (f32, f32),
        extent: (f32, f32),
        rotation: Option<f32>,
        flip_h: Option<bool>,
        flip_v: Option<bool>,
    ) -> Transform {
        Transform {
            offset,
            extent,
            rotation,
            flip_h,
            flip_v,
            shear_x: None,
            shear_y: None,
        }
    }

    const EPS: f32 = 1e-4;

    fn assert_close(actual: (f32, f32), expected: (f32, f32)) {
        assert!(
            (actual.0 - expected.0).abs() < EPS && (actual.1 - expected.1).abs() < EPS,
            "expected {:?}, got {:?}",
            expected,
            actual
        );
    }

    #[test]
    fn test_no_transform_equals_offset_plus_local() {
        // 无任何变换：连接点应等于 offset + 本地坐标（基础平移）
        let t = transform_with((0.0, 0.0), (100.0, 100.0), None, None, None);
        let p = cp(100.0, 50.0); // rect 右边中点
        assert_close(map_connection_point_to_global(&p, &t), (100.0, 50.0));
    }

    #[test]
    fn test_flip_h_only() {
        // 只 flip_h：x 取反+平移，y 不变
        let t = transform_with((0.0, 0.0), (100.0, 100.0), None, Some(true), None);
        let p = cp(100.0, 50.0); // 相对中心 (50, 0)，flip_h 后 (-50, 0)
        assert_close(map_connection_point_to_global(&p, &t), (0.0, 50.0));
    }

    #[test]
    fn test_flip_v_only() {
        // 只 flip_v：y 取反+平移，x 不变
        let t = transform_with((0.0, 0.0), (100.0, 100.0), None, None, Some(true));
        let p = cp(50.0, 100.0); // rect 下边中点，相对中心 (0, 50)，flip_v 后 (0, -50)
        assert_close(map_connection_point_to_global(&p, &t), (50.0, 0.0));
    }

    #[test]
    fn test_flip_v_matches_existing_render_layer_formula() {
        // 与现有渲染层 tile_render_helpers.rs 的
        // y' = -y + 2*sy + h_px 公式做交叉验证（同一输入应得到一致结果）。
        // 取 sy=0（即 offset.1=0）简化对照：现有公式退化为 y' = -y + h_px。
        let sy = 0.0_f32;
        let h_px = 100.0_f32;
        let local_y = 30.0_f32;
        let expected_old_formula = -local_y + 2.0 * sy + h_px;

        let t = transform_with((0.0, sy), (100.0, h_px), None, None, Some(true));
        let p = cp(0.0, local_y);
        let (_, new_y) = map_connection_point_to_global(&p, &t);
        assert!(
            (new_y - expected_old_formula).abs() < EPS,
            "new={}, old_formula={}",
            new_y,
            expected_old_formula
        );
    }

    #[test]
    fn test_rotation_90_around_center_not_top_left() {
        // 绕中心旋转 90°（顺时针），不是绕左上角旋转。
        // rect 右边中点 (100, 50)，w=h=100，中心 (50,50)。
        // 相对中心坐标 (50, 0)，顺时针转90°后应变为 (0, 50)（即变到底边中点位置）。
        let t = transform_with((0.0, 0.0), (100.0, 100.0), Some(90.0), None, None);
        let p = cp(100.0, 50.0);
        assert_close(map_connection_point_to_global(&p, &t), (50.0, 100.0));
    }

    #[test]
    fn test_rotation_180() {
        let t = transform_with((0.0, 0.0), (100.0, 100.0), Some(180.0), None, None);
        let p = cp(100.0, 50.0); // 相对中心 (50,0) -> 180° -> (-50,0)
        assert_close(map_connection_point_to_global(&p, &t), (0.0, 50.0));
    }

    #[test]
    fn test_rotation_270() {
        let t = transform_with((0.0, 0.0), (100.0, 100.0), Some(270.0), None, None);
        let p = cp(100.0, 50.0); // 相对中心 (50,0) -> 270°顺时针 -> (0,-50)
        assert_close(map_connection_point_to_global(&p, &t), (50.0, 0.0));
    }

    #[test]
    fn test_flip_h_and_flip_v_combined() {
        let t = transform_with((0.0, 0.0), (100.0, 100.0), None, Some(true), Some(true));
        let p = cp(100.0, 100.0); // 相对中心 (50,50) -> flip both -> (-50,-50)
        assert_close(map_connection_point_to_global(&p, &t), (0.0, 0.0));
    }

    #[test]
    fn test_flip_v_then_rotate_90_combined() {
        // 验证叠加顺序为"先 flip 再 rotate"。
        // rect 右边中点 (100, 50)，相对中心 (50, 0)。
        // flip_v: y取反 -> (50, 0)（y本来就是0，flip无影响，换个点验证更清楚）
        // 改用下边中点 (50, 100)，相对中心 (0, 50)。
        // flip_v -> (0, -50)。
        // 再顺时针90° -> (x'=0*cos90-(-50)*sin90=50, y'=0*sin90+(-50)*cos90=0) -> (50, 0)
        let t = transform_with((0.0, 0.0), (100.0, 100.0), Some(90.0), None, Some(true));
        let p = cp(50.0, 100.0);
        assert_close(map_connection_point_to_global(&p, &t), (100.0, 50.0));
    }

    #[test]
    fn test_non_origin_shape_offset_not_zero() {
        // 最容易出bug但最容易被偷懒跳过的场景：offset 不为 (0,0)。
        // 验证中心点计算是绝对坐标，而非误用局部坐标。
        // extent=(50,50), offset=(100,100)，中心的文档绝对坐标应为 (125,125)。
        let t = transform_with((100.0, 100.0), (50.0, 50.0), None, None, None);
        let p = cp(25.0, 25.0); // 局部坐标下的中心点本身，相对中心坐标为 (0,0)
        assert_close(map_connection_point_to_global(&p, &t), (125.0, 125.0));

        // 再验证一个非中心点：局部 (50, 25) 即右边中点，相对中心 (25, 0)
        let p2 = cp(50.0, 25.0);
        assert_close(map_connection_point_to_global(&p2, &t), (150.0, 125.0));
    }
}

// ============================================================================
// 预设形状数据表（第一批：rect / roundRect / ellipse）
// ============================================================================
//
// 数据来源：OnlyOffice `common/Drawings/Format/CreateGeometry.js` 逐行对照
// 翻译（行号见各形状注释）。`AddGuide(name, formula, x, y, z)` 的 formula
// 数字到操作码的映射已用 `Geometry.js` 第48-64行 `FORMULA_TYPE_*` 常量定义
// 核实（非猜测），对照表：
//   0=MulDiv 1=PlusMinus 2=PlusDiv 3=IfElse 4=Abs 5=At2 6=Cat2 7=Cos
//   8=Max 9=Mod 10=Pin 11=Sat2 12=Sin 13=Sqrt 14=Tan 15=Value 16=Min
// `AddPathCommand(cmd, ...)` 的 cmd 数字到指令类型的映射已用 `Geometry.js`
// 第1108-1156行 `AddPathCommand` 函数体核实：
//   0=路径元数据(跳过,不产生PathCmdDef) 1=moveTo 2=lineTo 3=arcTo(wR,hR,stAng,swAng)
//   4=quadBezTo(本批未用) 5=cubicBezTo(本批未用) 6=close 7=ellipticalArcTo(本批未用)
// `AddCnx`(连接点)/`AddHandleXY`(用户拖拽调整点句柄) 属于编辑交互信息，
// 不影响只读渲染路径本身，本次翻译不搬运，与本模块"解析阶段一次性求值
// 成绝对坐标路径"的定位一致。

/// `rect`：OnlyOffice CreateGeometry.js 第6741-6753行。无 adj 参数，
/// 路径直接是 w×h 矩形四角连线，是本批（也是187种预设里）最简单的一个，
/// 用于验证"无guide、无arcTo"场景下求值器不出错。
pub static RECT_FORMULA: PresetShapeFormula = PresetShapeFormula {
    name: "rect",
    default_adj: &[],
    guides: &[],
    path: &[
        PathCmdDef::MoveTo { x: GuideRef::named("l"), y: GuideRef::named("t") },
        PathCmdDef::LineTo { x: GuideRef::named("r"), y: GuideRef::named("t") },
        PathCmdDef::LineTo { x: GuideRef::named("r"), y: GuideRef::named("b") },
        PathCmdDef::LineTo { x: GuideRef::named("l"), y: GuideRef::named("b") },
        PathCmdDef::Close,
    ],
    cxn_lst: &[
        CxnDef { ang: GuideRef::named("_3cd4"), x: GuideRef::named("hc"), y: GuideRef::named("t") },
        CxnDef { ang: GuideRef::named("cd2"), x: GuideRef::named("l"), y: GuideRef::named("vc") },
        CxnDef { ang: GuideRef::named("cd4"), x: GuideRef::named("hc"), y: GuideRef::named("b") },
        CxnDef { ang: GuideRef::lit(0.0), x: GuideRef::named("r"), y: GuideRef::named("vc") },
    ],
};

