/// 按 OOXML `prst` 属性名字（如 "roundRect"）查找对应公式。
///
/// 线性查找：183项规模下（每个 slide 解析时对每个形状调用一次）
/// 性能可忽略不计，不引入额外依赖（HashMap/phf）做静态索引。
pub fn find_preset_shape(prst: &str) -> Option<&'static PresetShapeFormula> {
    ALL_PRESET_SHAPES.iter().find(|f| f.name == prst).copied()
}
