mod tests {
    use super::*;

    /// `donut` 端到端验证：w=h=100，adj取默认25000。dr=25，iwd2=ihd2=25。
    /// 断言：(1) 外圆4段圆心重合于几何中心(50,50)，半径50（复用ellipse
    /// 验证过的连续ArcTo游标衔接逻辑，外圆本身是ellipse的同构复用）；
    /// (2) 内圆4段圆心同样重合于(50,50)，半径25；(3) 内圆sweep_deg为
    /// 负值（-5400000），验证内外圆缠绕方向相反这一关键符号未被翻转——
    /// 若符号处理有误（比如resolve环节意外取绝对值），此断言会失败。
    #[test]
    fn test_donut_shape_inner_outer_circles() {
        let result = eval_preset_shape(&DONUT_FORMULA, 100.0, 100.0, &HashMap::new());
        assert_eq!(result.len(), 12); // (MoveTo+4ArcTo+Close) x2

        // 外圆：索引0=MoveTo, 1-4=ArcTo, 5=Close
        match &result[0] {
            PathCommand::MoveTo { x, y } => {
                assert!((x - 0.0).abs() < 1e-1);
                assert!((y - 50.0).abs() < 1e-1);
            }
            other => panic!("expected outer MoveTo, got {:?}", other),
        }
        for i in 1..=4 {
            match &result[i] {
                PathCommand::ArcTo { cx, cy, rx, ry, sweep_deg, .. } => {
                    assert!((cx - 50.0).abs() < 1e-1, "outer arc[{}] cx", i);
                    assert!((cy - 50.0).abs() < 1e-1, "outer arc[{}] cy", i);
                    assert!((rx - 50.0).abs() < 1e-1, "outer arc[{}] rx", i);
                    assert!((ry - 50.0).abs() < 1e-1, "outer arc[{}] ry", i);
                    assert!(*sweep_deg > 0.0, "outer arc[{}] sweep should be positive, got {}", i, sweep_deg);
                }
                other => panic!("expected outer ArcTo at {}, got {:?}", i, other),
            }
        }
        assert!(matches!(result[5], PathCommand::Close));

        // 内圆：索引6=MoveTo, 7-10=ArcTo, 11=Close
        match &result[6] {
            PathCommand::MoveTo { x, y } => {
                assert!((x - 25.0).abs() < 1e-1);
                assert!((y - 50.0).abs() < 1e-1);
            }
            other => panic!("expected inner MoveTo, got {:?}", other),
        }
        for i in 7..=10 {
            match &result[i] {
                PathCommand::ArcTo { cx, cy, rx, ry, sweep_deg, .. } => {
                    assert!((cx - 50.0).abs() < 1e-1, "inner arc[{}] cx", i);
                    assert!((cy - 50.0).abs() < 1e-1, "inner arc[{}] cy", i);
                    assert!((rx - 25.0).abs() < 1e-1, "inner arc[{}] rx", i);
                    assert!((ry - 25.0).abs() < 1e-1, "inner arc[{}] ry", i);
                    assert!(*sweep_deg < 0.0, "inner arc[{}] sweep should be negative, got {}", i, sweep_deg);
                }
                other => panic!("expected inner ArcTo at {}, got {:?}", i, other),
            }
        }
        assert!(matches!(result[11], PathCommand::Close));
    }

    /// `snip2SameRect` 端到端验证：w=h=100，adj1取默认16667（右上角
    /// 裁角深度16.667），adj2取默认0（左下角裁角深度0，即左下角退化
    /// 为直角，不裁切）。八个顶点精确手算：
    /// tx1=16.667, tx2=83.333, bx1=0, bx2=100, by1=100。
    /// 顶点(0)-(7)依次为(16.667,0)(83.333,0)(100,16.667)(100,100)
    /// (100,100)(0,100)(0,100)(0,16.667)——注意bx1=0导致第4/5点与
    /// 第6/7点两两重合（左下角退化为直角），这验证了adj2=0边界值
    /// 下dx/d guide链未产生NaN或异常坐标，公式在退化输入下依然稳定。
    #[test]
    fn test_snip2_same_rect_shape_vertices() {
        let result = eval_preset_shape(&SNIP2_SAME_RECT_FORMULA, 100.0, 100.0, &HashMap::new());
        assert_eq!(result.len(), 9); // MoveTo + 7×LineTo + Close

        let pts: Vec<(f32, f32)> = result.iter().map(|c| match c {
            PathCommand::MoveTo { x, y } => (*x, *y),
            PathCommand::LineTo { x, y } => (*x, *y),
            PathCommand::Close => (-1.0, -1.0),
            other => panic!("unexpected command in snip2SameRect: {:?}", other),
        }).collect();

        let expect = [
            (16.667, 0.0),
            (83.333, 0.0),
            (100.0, 16.667),
            (100.0, 100.0),
            (100.0, 100.0),
            (0.0, 100.0),
            (0.0, 100.0),
            (0.0, 16.667),
        ];
        for (i, (ex, ey)) in expect.iter().enumerate() {
            let (ax, ay) = pts[i];
            assert!((ax - ex).abs() < 1e-1 && (ay - ey).abs() < 1e-1,
                "vertex {} expected ({},{}), got ({},{})", i, ex, ey, ax, ay);
        }
    }

    /// `star5` 端到端验证：w=h=200，adj/hf/vf均用默认值。三角函数
    /// guide链的精确坐标不便手算，改用结构性质断言：
    /// (1) 10个顶点+Close，共11条路径指令；
    /// (2) 顶部顶点(hc,t)不涉及三角函数计算，可精确断言；
    /// (3) 左右对称性：x1/x4关于hc对称、x2/x3关于hc对称、
    ///     sx1/sx4关于hc对称、sx2/sx3关于hc对称，且对应y坐标相等
    ///     （y1==y1, y2==y2左右共用，sy1/sy2同理）——这验证了
    ///     Cos guide链（dx1/dx2/sdx1/sdx2）的符号处理和PlusMinus
    ///     左右两侧guide（x1 vs x4, x2 vs x3等）的对称性正确，
    ///     即便不知道具体数值，对称性错误也能被捕获。
    #[test]
    fn test_star5_shape_structure_and_symmetry() {
        let result = eval_preset_shape(&STAR5_FORMULA, 200.0, 200.0, &HashMap::new());
        assert_eq!(result.len(), 11); // MoveTo + 9×LineTo + Close

        let pts: Vec<(f32, f32)> = result.iter().map(|c| match c {
            PathCommand::MoveTo { x, y } => (*x, *y),
            PathCommand::LineTo { x, y } => (*x, *y),
            PathCommand::Close => (-1.0, -1.0),
            other => panic!("unexpected command in star5: {:?}", other),
        }).collect();

        // 顶部顶点 (hc, t)，索引2（MoveTo=x1y1, LineTo1=sx2sy1, LineTo2=hc,t）
        let hc = 100.0_f32;
        let top_y = 0.0_f32;
        assert!((pts[2].0 - hc).abs() < 1e-2, "top vertex x should be hc=100, got {}", pts[2].0);
        assert!((pts[2].1 - top_y).abs() < 1e-2, "top vertex y should be t=0, got {}", pts[2].1);

        // 左右对称性：x1(pts[0].0) 与 x4(pts[4].0) 应关于 hc 对称
        let x1 = pts[0].0;
        let x4 = pts[4].0;
        assert!(((x1 - hc) + (x4 - hc)).abs() < 1e-2,
            "x1({}) and x4({}) should be symmetric around hc({})", x1, x4, hc);
        let y1_left = pts[0].1;
        let y1_right = pts[4].1;
        assert!((y1_left - y1_right).abs() < 1e-2,
            "y1 should match on both sides: {} vs {}", y1_left, y1_right);

        // sx2(pts[1].0) 与 sx3(pts[3].0) 对称
        let sx2 = pts[1].0;
        let sx3 = pts[3].0;
        assert!(((sx2 - hc) + (sx3 - hc)).abs() < 1e-2,
            "sx2({}) and sx3({}) should be symmetric around hc({})", sx2, sx3, hc);

        // x2(pts[8].0) 与 x3(pts[6].0) 对称
        let x2 = pts[8].0;
        let x3 = pts[6].0;
        assert!(((x2 - hc) + (x3 - hc)).abs() < 1e-2,
            "x2({}) and x3({}) should be symmetric around hc({})", x2, x3, hc);

        // sx1(pts[9].0) 与 sx4(pts[5].0) 对称
        let sx1 = pts[9].0;
        let sx4 = pts[5].0;
        assert!(((sx1 - hc) + (sx4 - hc)).abs() < 1e-2,
            "sx1({}) and sx4({}) should be symmetric around hc({})", sx1, sx4, hc);

        // 底部中点顶点 hc, sy3（索引7）：x坐标应精确为hc
        assert!((pts[7].0 - hc).abs() < 1e-2, "bottom-mid vertex x should be hc, got {}", pts[7].0);
    }

    /// `chevron` 完整版端到端验证：w=h=100，adj取默认值50000。
    /// maxAdj=100000*100/100=100000；a=Pin(0,50000,100000)=50000；
    /// x1=100*50000/100000=50；x2=100-50=50。此时x1=x2=50，形状退化为
    /// 对称箭头，六个顶点应精确为(0,0)(50,0)(100,50)(50,100)(0,100)(50,50)。
    /// 这是本次搬运chevron完整版（区别于v23/Part1的内联子集测试）后
    /// 首次对CHEVRON_FORMULA本身的端到端验证。
    #[test]
    fn test_chevron_shape_vertices() {
        let result = eval_preset_shape(&CHEVRON_FORMULA, 100.0, 100.0, &HashMap::new());
        assert_eq!(result.len(), 7); // MoveTo + 5×LineTo + Close
        let pts: Vec<(f32, f32)> = result.iter().map(|c| match c {
            PathCommand::MoveTo { x, y } => (*x, *y),
            PathCommand::LineTo { x, y } => (*x, *y),
            PathCommand::Close => (-1.0, -1.0),
            other => panic!("unexpected command in chevron: {:?}", other),
        }).collect();
        let expect = [
            (0.0, 0.0), (50.0, 0.0), (100.0, 50.0),
            (50.0, 100.0), (0.0, 100.0), (50.0, 50.0),
        ];
        for (i, (ex, ey)) in expect.iter().enumerate() {
            let (ax, ay) = pts[i];
            assert!((ax - ex).abs() < 1e-2 && (ay - ey).abs() < 1e-2,
                "vertex {} expected ({},{}), got ({},{})", i, ex, ey, ax, ay);
        }
    }

    /// `rect` 形状端到端验证：w=h=100 时四个顶点应精确落在矩形四角，
    /// 这是本批数据里最简单的回归基准（无guide、无arcTo）。
    #[test]
    fn test_rect_shape_vertices() {
        let result = eval_preset_shape(&RECT_FORMULA, 100.0, 100.0, &HashMap::new());
        assert_eq!(result.len(), 5);
        let pts: Vec<(f32, f32)> = result.iter().map(|c| match c {
            PathCommand::MoveTo { x, y } => (*x, *y),
            PathCommand::LineTo { x, y } => (*x, *y),
            PathCommand::Close => (-1.0, -1.0),
            other => panic!("unexpected command in rect: {:?}", other),
        }).collect();
        assert_eq!(pts[0], (0.0, 0.0));
        assert_eq!(pts[1], (100.0, 0.0));
        assert_eq!(pts[2], (100.0, 100.0));
        assert_eq!(pts[3], (0.0, 100.0));
    }

    /// `roundRect` 端到端验证：w=h=100，adj取默认值16667。
    /// x1 = ss*a/100000 = 100*16667/100000 = 16.667（a经Pin(0,16667,50000)
    /// clamp后仍是16667，未触发clamp边界）。验证起点MoveTo(l,x1)及第一段
    /// ArcTo的圆心——这是本次会话新增ArcTo游标追踪机制首次在真实（非
    /// 测试构造）形状数据上验证，起点(0,16.667)，stAng=cd2(=180*60000)，
    /// 圆心公式 cx=cur_x-wR*cos(stAng), cy=cur_y-hR*sin(stAng)：
    /// cos(180°)=-1, sin(180°)=0，故 cx=0-16.667*(-1)=16.667, cy=16.667-0=16.667，
    /// 即左上角圆角的圆心应在(x1,x1)，与OOXML roundRect几何直觉一致
    /// （左上角圆角圆心确实应偏移(x1,x1)，不贴边）。
    #[test]
    fn test_round_rect_shape_first_arc_center() {
        let result = eval_preset_shape(&ROUND_RECT_FORMULA, 100.0, 100.0, &HashMap::new());
        assert!(result.len() >= 2);

        match &result[0] {
            PathCommand::MoveTo { x, y } => {
                assert!((x - 0.0).abs() < 1e-2, "expected x~0, got {}", x);
                assert!((y - 16.667).abs() < 1e-1, "expected y~16.667, got {}", y);
            }
            other => panic!("expected MoveTo, got {:?}", other),
        }

        match &result[1] {
            PathCommand::ArcTo { cx, cy, rx, ry, .. } => {
                assert!((cx - 16.667).abs() < 1e-1, "expected cx~16.667, got {}", cx);
                assert!((cy - 16.667).abs() < 1e-1, "expected cy~16.667, got {}", cy);
                assert!((rx - 16.667).abs() < 1e-1);
                assert!((ry - 16.667).abs() < 1e-1);
            }
            other => panic!("expected ArcTo, got {:?}", other),
        }
    }

    /// `ellipse` 端到端验证（本批最关键的回归测试）：w=h=100，四段90度
    /// ArcTo首尾相接、段间无显式MoveTo/LineTo，纯靠游标追踪衔接。
    /// 断言：(1) 起点(0,50)；(2) 四段圆心均应重合于椭圆几何中心(50,50)，
    /// 因为w=h=100时这是正圆，四段弧共享同一圆心；(3) 若游标追踪有累积
    /// 误差，四个圆心会逐渐漂移偏离(50,50)，本测试逐一断言四段而非只测
    /// 首段，专门覆盖"连续arcTo游标衔接是否稳定"这一点。
    #[test]
    fn test_ellipse_shape_arc_centers_coincide() {
        let result = eval_preset_shape(&ELLIPSE_FORMULA, 100.0, 100.0, &HashMap::new());
        assert_eq!(result.len(), 6); // MoveTo + 4×ArcTo + Close

        match &result[0] {
            PathCommand::MoveTo { x, y } => {
                assert!((x - 0.0).abs() < 1e-2);
                assert!((y - 50.0).abs() < 1e-1);
            }
            other => panic!("expected MoveTo, got {:?}", other),
        }

        for i in 1..=4 {
            match &result[i] {
                PathCommand::ArcTo { cx, cy, rx, ry, .. } => {
                    assert!((cx - 50.0).abs() < 1e-1, "arc[{}] cx should be ~50, got {}", i, cx);
                    assert!((cy - 50.0).abs() < 1e-1, "arc[{}] cy should be ~50, got {}", i, cy);
                    assert!((rx - 50.0).abs() < 1e-1, "arc[{}] rx should be ~50, got {}", i, rx);
                    assert!((ry - 50.0).abs() < 1e-1, "arc[{}] ry should be ~50, got {}", i, ry);
                }
                other => panic!("expected ArcTo at index {}, got {:?}", i, other),
            }
        }
    }

    /// ArcTo 游标追踪验证：MoveTo(10,0) 后接 ArcTo(wr=10,hr=10,stAng=0,swAng=90*60000)，
    /// 几何上应等价于"以原点为圆心、半径10的单位圆，从(10,0)逆时针扫90度到(0,10)"。
    /// 验证圆心反推公式 cx=cur_x-wR*cos(stAng), cy=cur_y-hR*sin(stAng) 及游标终点更新
    /// end_ang=stAng+swAng 的正确性，这是本次会话（ArcTo游标追踪）唯一新增的专项测试。
    #[test]
    fn test_arcto_cursor_quarter_circle() {
        static PATH: &[PathCmdDef] = &[
            PathCmdDef::MoveTo { x: GuideRef::lit(10.0), y: GuideRef::lit(0.0) },
            PathCmdDef::ArcTo {
                wr: GuideRef::lit(10.0),
                hr: GuideRef::lit(10.0),
                st_ang: GuideRef::lit(0.0),
                sw_ang: GuideRef::lit(90.0 * 60000.0),
            },
        ];
        static FORMULA: PresetShapeFormula = PresetShapeFormula {
            name: "test_arcto_quarter_circle",
            guides: &[],
            default_adj: &[],
            path: PATH,
            cxn_lst: &[],
        };

        let result = eval_preset_shape(&FORMULA, 100.0, 100.0, &HashMap::new());
        assert_eq!(result.len(), 2);

        match &result[0] {
            PathCommand::MoveTo { x, y } => {
                assert!((x - 10.0).abs() < 1e-3);
                assert!((y - 0.0).abs() < 1e-3);
            }
            other => panic!("expected MoveTo, got {:?}", other),
        }

        match &result[1] {
            PathCommand::ArcTo { cx, cy, rx, ry, start_deg, sweep_deg } => {
                assert!((cx - 0.0).abs() < 1e-3, "cx should be ~0, got {}", cx);
                assert!((cy - 0.0).abs() < 1e-3, "cy should be ~0, got {}", cy);
                assert!((rx - 10.0).abs() < 1e-3);
                assert!((ry - 10.0).abs() < 1e-3);
                assert!((start_deg - 0.0).abs() < 1e-3);
                assert!((sweep_deg - 90.0 * 60000.0).abs() < 1.0);
            }
            other => panic!("expected ArcTo, got {:?}", other),
        }
    }

    /// 端到端验证：chevron 形状关键子集（已从 OnlyOffice CreateGeometry.js
    /// 逐行对照移植），adj=50000（默认值），w=h=100，验证求值不panic且
    /// 关键点坐标符合"人"字形几何直觉。
    #[test]
    fn test_eval_chevron_default() {
        static GUIDES: &[GuideDef] = &[
            GuideDef { name: "maxAdj", op: GuideOp::MulDiv,
                args: [GuideRef::named("w"), GuideRef::lit(100000.0), GuideRef::named("ss")] },
            GuideDef { name: "a", op: GuideOp::Pin,
                args: [GuideRef::lit(0.0), GuideRef::named("adj"), GuideRef::named("maxAdj")] },
            GuideDef { name: "x1", op: GuideOp::MulDiv,
                args: [GuideRef::named("ss"), GuideRef::named("a"), GuideRef::lit(100000.0)] },
            GuideDef { name: "x2", op: GuideOp::PlusMinus,
                args: [GuideRef::named("r"), GuideRef::lit(0.0), GuideRef::named("x1")] },
        ];
        static PATH: &[PathCmdDef] = &[
            PathCmdDef::MoveTo { x: GuideRef::named("l"), y: GuideRef::named("t") },
            PathCmdDef::LineTo { x: GuideRef::named("x2"), y: GuideRef::named("t") },
            PathCmdDef::Close,
        ];
        static FORMULA: PresetShapeFormula = PresetShapeFormula {
            name: "chevron_test_subset",
            default_adj: &[("adj", 50000.0)],
            guides: GUIDES,
            path: PATH,
            cxn_lst: &[],
        };

        let result = eval_preset_shape(&FORMULA, 100.0, 100.0, &HashMap::new());
        assert_eq!(result.len(), 3);
        match result[0] {
            PathCommand::MoveTo { x, y } => { assert_eq!(x, 0.0); assert_eq!(y, 0.0); }
            _ => panic!("expected MoveTo"),
        }
        match result[1] {
            PathCommand::LineTo { x, y } => { assert_eq!(x, 50.0); assert_eq!(y, 0.0); }
            _ => panic!("expected LineTo"),
        }
    }

    #[test]
    fn test_pin_clamp_semantics() {
        let def = GuideDef { name: "r", op: GuideOp::Pin,
            args: [GuideRef::lit(10.0), GuideRef::lit(5.0), GuideRef::lit(20.0)] };
        let mut ctx = HashMap::new();
        eval_guide(&def, &mut ctx);
        assert_eq!(ctx["r"], 10.0);

        let def2 = GuideDef { name: "r2", op: GuideOp::Pin,
            args: [GuideRef::lit(10.0), GuideRef::lit(25.0), GuideRef::lit(20.0)] };
        eval_guide(&def2, &mut ctx);
        assert_eq!(ctx["r2"], 20.0);

        let def3 = GuideDef { name: "r3", op: GuideOp::Pin,
            args: [GuideRef::lit(10.0), GuideRef::lit(15.0), GuideRef::lit(20.0)] };
        eval_guide(&def3, &mut ctx);
        assert_eq!(ctx["r3"], 15.0);
    }

    #[test]
    fn test_mod_euclidean_distance() {
        let def = GuideDef { name: "d", op: GuideOp::Mod,
            args: [GuideRef::lit(3.0), GuideRef::lit(4.0), GuideRef::lit(0.0)] };
        let mut ctx = HashMap::new();
        eval_guide(&def, &mut ctx);
        assert_eq!(ctx["d"], 5.0);
    }

    /// PPTX-11 part5 冒烟测试：遍历 ALL_PRESET_SHAPES 全部183项，
    /// 用各自 default_adj 默认值 + w=h=100 求值，只验证不panic、
    /// 路径非空、坐标全部有限（非NaN/非Infinite）。不验证坐标语义
    /// 正确性（那是roe-ext_progress_v27.md §五-E 抽样核对的范畴，
    /// 本测试是更基础的"不崩溃"防线）。
    #[test]
    fn test_get_connection_points_rect_absolute_coords() {
        // 数值求值核对（区别于前面测试的静态数据结构核对）：w=100,h=100
        // 的 rect，四个连接点应落在四边中点的绝对坐标，且 idx 顺序保持
        // 声明顺序（上→左→下→右，与 LOK 官方定义/OnlyOffice 源码交叉
        // 验证过的顺序一致）。
        let pts = get_connection_points(&RECT_FORMULA, 100.0, 100.0, &HashMap::new());
        assert_eq!(pts.len(), 4);
        // idx=0: 上边中点 (50, 0)
        assert_eq!(pts[0].idx, 0);
        assert!((pts[0].x - 50.0).abs() < 1e-3);
        assert!((pts[0].y - 0.0).abs() < 1e-3);
        // idx=1: 左边中点 (0, 50)
        assert!((pts[1].x - 0.0).abs() < 1e-3);
        assert!((pts[1].y - 50.0).abs() < 1e-3);
        // idx=2: 下边中点 (50, 100)
        assert!((pts[2].x - 50.0).abs() < 1e-3);
        assert!((pts[2].y - 100.0).abs() < 1e-3);
        // idx=3: 右边中点 (100, 50)，ang应为0.0（数字字面量）
        assert!((pts[3].x - 100.0).abs() < 1e-3);
        assert!((pts[3].y - 50.0).abs() < 1e-3);
        assert!((pts[3].angle_60000th_deg - 0.0).abs() < 1e-3);
    }

    #[test]
    fn test_get_connection_points_triangle_depends_on_adj() {
        // 三角形连接点依赖形状私有guide（x1/x2/x3，随adj参数变化），
        // 核对默认adj（顶点居中，50000/100000=0.5）时的绝对坐标，
        // 确认 get_connection_points 与 eval_preset_shape 共享同一套
        // ctx 求值结果一致（顶点idx=0应为 (50, 0)，即 x2=w*a/100000=
        // 100*0.5=50，顶部y=t=0）。
        let pts = get_connection_points(&TRIANGLE_FORMULA, 100.0, 100.0, &HashMap::new());
        assert_eq!(pts.len(), 6);
        // idx=0: 顶点 (x2, t) = (50, 0)（默认adj=50000时对称三角形）
        assert!((pts[0].x - 50.0).abs() < 1e-3);
        assert!((pts[0].y - 0.0).abs() < 1e-3);
    }

    #[test]
    fn test_get_connection_points_empty_for_shapes_without_cxn_lst() {
        // 无cxnLst定义的形状（如connector家族自身）应返回空Vec，不panic。
        // 用 STRAIGHT_CONNECTOR1_FORMULA 或类似形状核对（若该常量名不存在，
        // 用任意已知 cxn_lst 为空的形状替代——此测试的关键断言是"不panic
        // 且返回空"，具体挑哪个形状不影响断言意图）。
        let empty_formula = PresetShapeFormula {
            name: "test_no_cxn",
            default_adj: &[],
            guides: &[],
            path: &[],
            cxn_lst: &[],
        };
        let pts = get_connection_points(&empty_formula, 100.0, 100.0, &HashMap::new());
        assert!(pts.is_empty());
    }

    #[test]
    fn test_cxn_lst_coverage_174_of_187() {
        // 2026-09 新增：174/187 个预设形状应有非空 cxn_lst（本次会话从
        // OnlyOffice CreateGeometry.js 批量翻译），其余13个（多为connector
        // 家族自身）应为空但不panic。回归探测：数字不能低于174，也不应
        // 无故增长（若增长，说明有人手工加了新形状但未同步更新此断言，
        // 需要人工确认后再放宽此数字）。
        let with_cxn = ALL_PRESET_SHAPES.iter().filter(|f| !f.cxn_lst.is_empty()).count();
        assert_eq!(with_cxn, 174, "有 cxn_lst 定义的形状数应为174，若变化需人工复核");
    }

    #[test]
    fn test_cxn_lst_rect_matches_lok_official_definition() {
        // 人工核对基准：LOK presetShapeDefinitions.xml 与 OnlyOffice
        // CreateGeometry.js 交叉验证过的 rect 连接点顺序（2026-09核实，
        // 上→左→下→右，idx即声明顺序，非"隐式顺时针从上开始"的通用规律，
        // 每个形状需要单独核实，不能套用这个顺序到其他形状）。
        let cxns = RECT_FORMULA.cxn_lst;
        assert_eq!(cxns.len(), 4);
        // idx=0: 上边中点 (hc, t)
        match (&cxns[0].x, &cxns[0].y) {
            (GuideRef::Named(x), GuideRef::Named(y)) => {
                assert_eq!(*x, "hc");
                assert_eq!(*y, "t");
            }
            _ => panic!("rect idx=0 应为具名引用 (hc, t)"),
        }
        // idx=3: 右边中点 (r, vc)，ang 应为数字字面量 0.0
        match (&cxns[3].ang, &cxns[3].x, &cxns[3].y) {
            (GuideRef::Literal(ang), GuideRef::Named(x), GuideRef::Named(y)) => {
                assert_eq!(*ang, 0.0);
                assert_eq!(*x, "r");
                assert_eq!(*y, "vc");
            }
            _ => panic!("rect idx=3 应为 (ang=0.0字面量, r, vc)"),
        }
    }

    #[test]
    fn test_cxn_lst_triangle_non_symmetric_shape() {
        // 抽样核对非对称形状（三角形，连接点引用形状私有guide如x1/x2/x3，
        // 而非仅内置常量），确认 cxn_lst 与 path/guides 共享同一套具名
        // 变量语义，翻译时未把这些私有guide名弄丢。
        let cxns = TRIANGLE_FORMULA.cxn_lst;
        assert_eq!(cxns.len(), 6);
        match &cxns[1].x {
            GuideRef::Named(x) => assert_eq!(*x, "x1"),
            _ => panic!("triangle idx=1 的 x 应引用形状私有guide x1"),
        }
    }

    #[test]
    fn test_all_preset_shapes_eval_smoke() {
        let mut failures: Vec<String> = Vec::new();

        for formula in ALL_PRESET_SHAPES {
            let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                eval_preset_shape(formula, 100.0, 100.0, &HashMap::new())
            }));

            match result {
                Err(_) => {
                    failures.push(format!("{}: panicked during eval", formula.name));
                }
                Ok(path) => {
                    if path.is_empty() {
                        failures.push(format!("{}: empty path", formula.name));
                        continue;
                    }
                    for (i, cmd) in path.iter().enumerate() {
                        let coords: Vec<f32> = match cmd {
                            PathCommand::MoveTo { x, y } => vec![*x, *y],
                            PathCommand::LineTo { x, y } => vec![*x, *y],
                            PathCommand::QuadTo { x1, y1, x, y } => vec![*x1, *y1, *x, *y],
                            PathCommand::CubicTo { x1, y1, x2, y2, x, y } => {
                                vec![*x1, *y1, *x2, *y2, *x, *y]
                            }
                            PathCommand::ArcTo { cx, cy, rx, ry, start_deg, sweep_deg } => {
                                vec![*cx, *cy, *rx, *ry, *start_deg, *sweep_deg]
                            }
                            PathCommand::Close => vec![],
                        };
                        if coords.iter().any(|v| !v.is_finite()) {
                            failures.push(format!(
                                "{}: non-finite coordinate at path[{}] ({:?})",
                                formula.name, i, cmd
                            ));
                            break;
                        }
                    }
                }
            }
        }

        assert!(
            failures.is_empty(),
            "{} / {} preset shapes failed smoke test:\n{}",
            failures.len(),
            ALL_PRESET_SHAPES.len(),
            failures.join("\n")
        );
    }
}
